using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;
public static class Tools101Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool v,string s){if(!v)throw new Exception(s);}
 static Dictionary<string,GameObject> Build(string stage){string folder="Assets/Imported101-"+stage;if(stage=="before"&&AssetDatabase.IsValidFolder(folder)){var cached=new Dictionary<string,GameObject>();foreach(var file in Directory.GetFiles(Path.Combine(Root,folder),"small-*.prefab"))cached.Add(Path.GetFileNameWithoutExtension(file).Substring(6),AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/"+Path.GetFileName(file)));Check(cached.Count==43,"43 baseline prefabs");return cached;}Check(!AssetDatabase.IsValidFolder(folder),"Fresh test output required");AssetDatabase.CreateFolder("Assets",folder.Substring(7));var root=new GameObject("Mining tools "+stage);var p=new Dictionary<string,GameObject>();Check(SmallPropsV1.Build(Path.Combine(Root,"Input101-"+(stage=="after3"?"after2":stage)),folder,root.transform,Shader.Find("MapSharedProps/Lit"),p)==1&&p.Count==43,"43 prefabs/one placement");if(stage=="after3"){var prototype=p["miningtools"].GetComponent<MeshFilter>().sharedMesh;var placed=root.GetComponentsInChildren<MeshFilter>().Single().sharedMesh;Check(prototype.uv.SequenceEqual(placed.uv),"grounded atlas UV and vertical flip exact");Check(placed.bounds.min.y>=-.003f,"ground contact");}PrefabUtility.SaveAsPrefabAsset(root,"Assets/tools101-"+stage+".prefab");UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();return p;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence101Import");Directory.CreateDirectory(output);try{
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var before=Build("before");var after=Build("after3");
 Check(before["miningtools"].GetComponentsInChildren<Collider>(true).Length==0&&after["miningtools"].GetComponentsInChildren<Collider>(true).Length==0,"nonblocking tools preserved");
 foreach(var id in before.Keys.Where(x=>x!="miningtools"))Check(before[id].GetComponent<MeshFilter>().sharedMesh==after[id].GetComponent<MeshFilter>().sharedMesh,"unrelated mesh exact "+id);
 var m=after["miningtools"].GetComponent<MeshFilter>().sharedMesh;Check(m.vertexCount/3<=650,"tool triangle budget");Check(m.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)),"finite geometry");
 var ma=after["miningtools"].GetComponent<Renderer>().sharedMaterial;var other=after["smallbarrel"].GetComponent<Renderer>().sharedMaterial;Check(ma.GetTexture("_BaseMap")==other.GetTexture("_BaseMap")&&ma.GetTexture("_BaseMap").width==1024,"existing atlas shared with barrel");
 Check(after["miningtools"].GetComponentsInChildren<Light>(true).Length==0,"no added light");
 File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"cases\":[\"before\",\"after3\"],\"prefabsPerCase\":43,\"placementsPerCase\":1,\"nonblockingColliderPreserved\":true,\"unrelated42MeshesExact\":true,\"existingAtlasSharedWithBarrel\":true,\"newTextureBytes\":0,\"groundedAtlasUvExact\":true,\"oldReaderGenerated43\":true,\"playerExecuted\":false}");
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
